namespace Ordering;

/// <summary>
/// Coordinates checkout services while preserving the original checkout API.
/// </summary>
public sealed class CheckoutCoordinator
{
    private readonly CheckoutPricingService _pricing;
    private readonly CheckoutFlowService _flow;
    private readonly CheckoutPromotionService _promotions;
    private readonly CheckoutAuditService _audit;
    private readonly CheckoutTenderService _tender;

    public CheckoutCoordinator()
    {
        _pricing = new CheckoutPricingService();
        _flow = new CheckoutFlowService(_pricing);
        _promotions = new CheckoutPromotionService(_pricing);
        _audit = new CheckoutAuditService();
        _tender = new CheckoutTenderService(_pricing);
    }

    public string BeginCheckout(Order order, Customer customer) =>
        _flow.BeginCheckout(order, customer);

    public bool AdvanceStep(string step) =>
        _flow.AdvanceStep(step);

    public string CompleteCheckout(Order order, Customer customer) =>
        _flow.CompleteCheckout(order, customer);

    public decimal PriceLine(OrderLine line) =>
        _pricing.PriceLine(line);

    public decimal PriceOrder(Order order) =>
        _pricing.PriceOrder(order);

    public decimal SummariseCharges(Order order, Customer customer) =>
        _pricing.SummariseCharges(order, customer);

    public decimal ApplyPromo(Order order, string code) =>
        _promotions.ApplyPromo(order, code);

    public bool ValidatePromo(string code) =>
        _promotions.ValidatePromo(code);

    public void RecordAudit(string entry) =>
        _audit.Record(entry);

    public IReadOnlyList<string> AuditTrail(Order order) =>
        _audit.GetTrail(order);

    public string ResolveTender(Order order, Customer customer) =>
        _tender.Resolve(order, customer);

    public IReadOnlyList<string> ScheduleFulfilment(Order order) =>
        CheckoutFulfilmentService.Schedule(order);

    public int StepCount => _flow.StepCount;
}

internal sealed class CheckoutFlowService
{
    private readonly List<string> _completedSteps = new();
    private readonly CheckoutPricingService _pricing;

    internal CheckoutFlowService(CheckoutPricingService pricing)
    {
        _pricing = pricing;
    }

    internal string BeginCheckout(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";
        if (order.Lines.Count == 0)
            return "empty order";

        _completedSteps.Clear();
        _completedSteps.Add("begin");
        return "ok";
    }

    internal bool AdvanceStep(string step)
    {
        if (string.IsNullOrWhiteSpace(step))
            return false;
        if (_completedSteps.Contains(step))
            return false;

        _completedSteps.Add(step);
        return true;
    }

    internal string CompleteCheckout(Order order, Customer customer)
    {
        if (!_completedSteps.Contains("begin"))
            return "not started";
        if (order.Lines.Count == 0)
            return "empty order";

        var total = _pricing.PriceOrder(order);
        if (customer.Tier == CustomerTier.Wholesale && total > 0m)
            total *= 0.97m;

        _completedSteps.Add("complete");
        return total > 0m ? $"charged {total}" : "nothing due";
    }

    internal int StepCount => _completedSteps.Count;
}

internal sealed class CheckoutPricingService
{
    private readonly Dictionary<string, decimal> _priceBook =
        new(StringComparer.Ordinal);

    internal decimal PriceLine(OrderLine line)
    {
        if (_priceBook.TryGetValue(line.Sku, out var book))
            return book * line.Quantity;
        if (line.UnitPrice > 0m)
            return line.UnitPrice * line.Quantity;
        return 0m;
    }

    internal decimal PriceOrder(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            total += PriceLine(line);
        }

        if (order.DiscountOverride is { } ovr && ovr > 0m)
            total -= ovr;

        return total < 0m ? 0m : total;
    }

    internal decimal SummariseCharges(Order order, Customer customer)
    {
        var goods = PriceOrder(order);
        decimal shipping;

        if (order.Channel == OrderChannel.Marketplace)
            shipping = 0m;
        else if (customer.Tier == CustomerTier.Wholesale)
            shipping = 5m;
        else if (goods > 100m)
            shipping = 0m;
        else
            shipping = 4.5m;

        if (customer.Tier == CustomerTier.Blocked && goods > 0m)
            shipping += 0m;
        if (order.Channel == OrderChannel.Phone)
            shipping += 1m;

        return goods + shipping;
    }
}

internal sealed class CheckoutPromotionService
{
    private readonly CheckoutPricingService _pricing;
    private readonly Dictionary<string, decimal> _promoRates =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["WELCOME"] = 0.10m,
            ["VIP"] = 0.20m,
        };
    private readonly HashSet<string> _redeemed =
        new(StringComparer.OrdinalIgnoreCase);

    internal CheckoutPromotionService(CheckoutPricingService pricing)
    {
        _pricing = pricing;
    }

    internal decimal ApplyPromo(Order order, string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return 0m;
        if (!ValidatePromo(code))
            return 0m;
        if (_redeemed.Contains(order.Reference))
            return 0m;

        var rate = _promoRates.TryGetValue(code, out var value) ? value : 0m;
        var goods = _pricing.PriceOrder(order);
        _redeemed.Add(order.Reference);
        return rate > 0m ? goods * rate : 0m;
    }

    internal bool ValidatePromo(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return false;
        if (code.Length < 3)
            return false;

        return _promoRates.ContainsKey(code) ||
               code.StartsWith("TMP", StringComparison.Ordinal);
    }
}

internal sealed class CheckoutAuditService
{
    private readonly List<string> _entries = new();

    internal void Record(string entry)
    {
        if (!string.IsNullOrEmpty(entry))
            _entries.Add(entry);
    }

    internal IReadOnlyList<string> GetTrail(Order order)
    {
        var trail = new List<string>();
        foreach (var entry in _entries)
        {
            if (entry.Contains(order.Reference, StringComparison.Ordinal))
                trail.Add(entry);
        }

        if (trail.Count == 0)
            trail.Add("no entries");

        return trail;
    }
}

internal sealed class CheckoutTenderService
{
    private readonly CheckoutPricingService _pricing;

    internal CheckoutTenderService(CheckoutPricingService pricing)
    {
        _pricing = pricing;
    }

    internal string Resolve(Order order, Customer customer)
    {
        if (order.Lines.Count == 0)
            return "none";

        var goods = _pricing.PriceOrder(order);
        string tender;

        if (customer.Tier == CustomerTier.Wholesale)
            tender = "invoice";
        else if (goods > 500m)
            tender = "card-3ds";
        else if (goods > 0m)
            tender = "card";
        else
            tender = "none";

        if (order.Channel == OrderChannel.Phone && goods > 0m)
            tender = "mail-order";
        if (order.Channel == OrderChannel.Marketplace)
            tender = "marketplace-escrow";
        if (customer.Tier == CustomerTier.Blocked || goods < 0m)
            return "blocked";

        return tender;
    }
}

internal static class CheckoutFulfilmentService
{
    internal static IReadOnlyList<string> Schedule(Order order)
    {
        var tasks = new List<string>();
        if (order.Lines.Count == 0)
            return tasks;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                tasks.Add($"bulk {line.Sku}");
            else if (line.Quantity > 10)
                tasks.Add($"case {line.Sku}");
            else
                tasks.Add($"each {line.Sku}");
        }

        if (order.Channel == OrderChannel.Marketplace)
            tasks.Add("notify-marketplace");
        else if (order.Channel == OrderChannel.Phone && tasks.Count > 0)
            tasks.Add("callback");

        if (tasks.Count == 0)
            tasks.Add("hold");

        return tasks;
    }
}
